local SAVE_LOAD_MESSAGE_REQUEST = {  MESSAGE_ACTIVATEUSERFLOWREQUEST = 0,  MESSAGE_LOADFILELISTFLOWREQUEST = 1,  MESSAGE_LOADFLOWREQUEST = 2,  MESSAGE_USERSELECTIONRESPONSE = 3,  MESSAGE_USERSAVEFLOWREQUEST = 4,  MESSAGE_BOOTFLOWREQUEST = 5,  MESSAGE_AUTOLOADFLOWREQUEST = 6,  MESSAGE_AUTOLOADMULTIPLEGROUPSFLOWREQUEST = 7,  MESSAGE_PROGRESSSAVEFLOWREQUEST = 8}local BootFlow = {}function BootFlow:new(init)  print("[BootFlow]: new()")  local o = init or {}  setmetatable(o, self)  self.__index = self  o.services = {    SaveLoadService = o.api("SaveLoadService"),    CustomizationService = o.api("FifaCustomizationService"),    GameStateService = o.api("GameStateService")  }  o.nav.AddActionHandler("initSaveLoad", false, nil, function(action)    o.services.CustomizationService.InitFifaSetupData()  end  )  o.nav.AddActionHandler("sendSaveLoadMessage", false, nil, function(action, message)    o.services.SaveLoadService.CreateAndSendMessage(message)  end  )  return oendfunction BootFlow:finalize()  print("[BootFlow]: finalize()")  self.services.GameStateService.SetHomeController()  self.nav.RemoveActionHandler("initSaveLoad")  self.nav.RemoveActionHandler("sendSaveLoadMessage")endreturn BootFlow